from __future__ import annotations

import math
import os
import re
import subprocess
import sys
from datetime import datetime, date, time
from decimal import Decimal, InvalidOperation

# Install/verify required packages inside the executing interpreter.
def ensure_packages():
    packages = [("openpyxl", "openpyxl"), ("pandas", "pandas"), ("docx", "python-docx")]
    missing = []
    for module_name, pip_name in packages:
        try:
            __import__(module_name)
        except ImportError:
            missing.append(pip_name)
    if missing:
        try:
            subprocess.check_call([sys.executable, "-m", "pip", "install", *missing])
        except subprocess.CalledProcessError:
            # PEP 668 environments need this explicit override. This script is task-local.
            subprocess.check_call([sys.executable, "-m", "pip", "install", "--break-system-packages", *missing])

ensure_packages()

import openpyxl
from openpyxl import Workbook, load_workbook
from openpyxl.styles import Font
from openpyxl.utils.dataframe import dataframe_to_rows
from openpyxl.utils.datetime import from_excel
from docx import Document

# Pandas is required by the task. If installation was interrupted, the fallback writer still
# uses openpyxl, but pandas is installed/loaded where available for data manipulation.
import pandas as pd

SOURCE = "/root/Promo_Price_Check_Source.xlsx"
AUDIT = "/root/Promo_Register_Audit.xlsx"
BRIEF = "/root/Promo_Register_Brief.docx"

CANONICAL = [
    "Promo ID",
    "SKU",
    "Promo Price",
    "Register Price",
    "Promo Start Date",
    "Sale Date",
    "Promo End Date",
    "Store ID",
]
DATE_COLUMNS = ["Promo Start Date", "Sale Date", "Promo End Date"]
FORMATTED_HEADERS = CANONICAL + ["Price Error", "Window Error", "Total Errors", "Error Summary"]
SUMMARY_HEADERS = ["SKU", "Store ID", "Price Errors", "Window Errors", "Total Errors"]


def normalize_header(value):
    return re.sub(r"[^a-z0-9]+", "", str(value or "").strip().lower())


def choose_sheet(path):
    wb = load_workbook(path, read_only=True, data_only=True)
    target_norms = {normalize_header(c) for c in CANONICAL}
    best = None
    best_score = -1
    for ws in wb.worksheets:
        if ws.max_row < 1:
            continue
        headers = [cell.value for cell in next(ws.iter_rows(min_row=1, max_row=1))]
        score = len({normalize_header(h) for h in headers} & target_norms)
        if score > best_score:
            best = ws.title
            best_score = score
    if best is None or best_score < len(CANONICAL):
        raise ValueError(f"Could not identify a sheet with required columns; best={best!r}, score={best_score}")
    return best, wb.sheetnames


def read_source_as_dataframe(path, sheet_name):
    # Use pandas for the primary read. Preserve all source columns and row order.
    df = pd.read_excel(path, sheet_name=sheet_name, engine="openpyxl", dtype=object)
    return df


def map_columns(df):
    norm_to_actual = {}
    for col in df.columns:
        norm = normalize_header(col)
        if norm and norm not in norm_to_actual:
            norm_to_actual[norm] = col
    mapping = {}
    for canonical in CANONICAL:
        norm = normalize_header(canonical)
        if norm not in norm_to_actual:
            raise KeyError(f"Missing required column {canonical!r}. Available columns: {list(df.columns)!r}")
        mapping[norm_to_actual[norm]] = canonical
    return mapping


def excel_serial_to_datetime(value):
    try:
        return from_excel(float(value))
    except Exception:
        # Manual fallback for standard 1900 epoch, preserving Excel's leap-year quirk via openpyxl normally.
        return pd.to_datetime(value, errors="coerce")


def normalize_date_value(value):
    if value is None:
        return pd.NaT
    try:
        if pd.isna(value):
            return pd.NaT
    except Exception:
        pass
    if isinstance(value, pd.Timestamp):
        return value.to_pydatetime()
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime.combine(value, time.min)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if math.isnan(float(value)):
            return pd.NaT
        # Excel serial dates for plausible modern dates.
        if 1 <= float(value) <= 100000:
            return excel_serial_to_datetime(value)
        parsed = pd.to_datetime(value, errors="coerce")
        return parsed.to_pydatetime() if not pd.isna(parsed) else pd.NaT
    text = str(value).strip()
    if not text:
        return pd.NaT
    if re.fullmatch(r"\d+(\.\d+)?", text):
        number = float(text)
        if 1 <= number <= 100000:
            return excel_serial_to_datetime(number)
    parsed = pd.to_datetime(text, errors="coerce", infer_datetime_format=True)
    return parsed.to_pydatetime() if not pd.isna(parsed) else pd.NaT


def as_date(value):
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    if isinstance(value, pd.Timestamp):
        return value.date()
    if isinstance(value, datetime):
        return value.date()
    if isinstance(value, date):
        return value
    parsed = normalize_date_value(value)
    if parsed is pd.NaT or pd.isna(parsed):
        return None
    return parsed.date() if isinstance(parsed, datetime) else parsed


def to_decimal(value):
    if value is None:
        return None
    try:
        if pd.isna(value):
            return None
    except Exception:
        pass
    try:
        return Decimal(str(value).strip().replace("$", "").replace(",", ""))
    except (InvalidOperation, AttributeError):
        try:
            return Decimal(str(float(value)))
        except Exception:
            return None


def price_error(register_price, promo_price):
    r = to_decimal(register_price)
    p = to_decimal(promo_price)
    if r is None or p is None:
        return 1 if r != p else 0
    return 0 if abs(r - p) <= Decimal("0.000001") else 1


def window_error(sale_date, start_date, end_date):
    sale = as_date(sale_date)
    start = as_date(start_date)
    end = as_date(end_date)
    if sale is None or start is None or end is None:
        return 1
    return 1 if sale < start or sale > end else 0


def error_summary(price_flag, window_flag):
    if price_flag and window_flag:
        return "Price Error, Window Error"
    if price_flag:
        return "Price Error"
    if window_flag:
        return "Window Error"
    return "None"


def build_outputs():
    sheet_name, sheetnames = choose_sheet(SOURCE)
    print(f"Source workbook sheets: {sheetnames}")
    print(f"Selected source sheet: {sheet_name}")

    raw_df = read_source_as_dataframe(SOURCE, sheet_name)
    mapping = map_columns(raw_df)
    print(f"Column mapping: {mapping}")

    formatted = raw_df.rename(columns=mapping)[CANONICAL].copy()
    for col in DATE_COLUMNS:
        formatted[col] = formatted[col].apply(normalize_date_value)

    formatted["Price Error"] = formatted.apply(lambda r: price_error(r["Register Price"], r["Promo Price"]), axis=1)
    formatted["Window Error"] = formatted.apply(lambda r: window_error(r["Sale Date"], r["Promo Start Date"], r["Promo End Date"]), axis=1)
    formatted["Total Errors"] = formatted["Price Error"].astype(int) + formatted["Window Error"].astype(int)
    formatted["Error Summary"] = formatted.apply(lambda r: error_summary(int(r["Price Error"]), int(r["Window Error"])), axis=1)
    formatted = formatted[FORMATTED_HEADERS]

    summary_core = (
        formatted.groupby(["SKU", "Store ID"], dropna=False, sort=False)[["Price Error", "Window Error", "Total Errors"]]
        .sum()
        .reset_index()
        .rename(columns={"Price Error": "Price Errors", "Window Error": "Window Errors"})
    )
    summary_core = summary_core[summary_core["Total Errors"] > 0].copy()
    summary_core = summary_core.sort_values(by=["SKU", "Store ID"], ascending=[True, True], kind="mergesort")
    totals = {
        "Price Errors": int(formatted["Price Error"].sum()),
        "Window Errors": int(formatted["Window Error"].sum()),
        "Total Errors": int(formatted["Total Errors"].sum()),
    }
    grand_total = pd.DataFrame([{
        "SKU": "Grand Total",
        "Store ID": "-",
        "Price Errors": totals["Price Errors"],
        "Window Errors": totals["Window Errors"],
        "Total Errors": totals["Total Errors"],
    }])
    summary = pd.concat([summary_core[SUMMARY_HEADERS], grand_total], ignore_index=True)

    # Write workbook with openpyxl to control sheets, concrete values, and date formats.
    wb = Workbook()
    default = wb.active
    wb.remove(default)
    for name, df in [("RawData", raw_df), ("Formatted Data", formatted), ("Summary", summary)]:
        ws = wb.create_sheet(name)
        for row in dataframe_to_rows(df, index=False, header=True):
            ws.append(row)
        for cell in ws[1]:
            cell.font = Font(bold=True)
        if name == "Formatted Data":
            for col_idx, header in enumerate(FORMATTED_HEADERS, start=1):
                if header in DATE_COLUMNS:
                    for cell in ws.iter_cols(min_col=col_idx, max_col=col_idx, min_row=2, max_row=ws.max_row):
                        for c in cell:
                            c.number_format = "yyyy-mm-dd"
        ws.freeze_panes = "A2"
    wb.save(AUDIT)
    print(f"Wrote audit workbook: {AUDIT}")

    high_priority = (
        summary_core.groupby("SKU", dropna=False)["Total Errors"].sum().reset_index()
        .sort_values(["Total Errors", "SKU"], ascending=[False, True])
    )
    top_skus = [str(x) for x in high_priority["SKU"].head(2).tolist()]
    if len(top_skus) < 2 and len(high_priority) > 0:
        top_skus = [str(x) for x in high_priority["SKU"].tolist()]
    sku_phrase = ", ".join(top_skus) if top_skus else "no exception SKUs"

    doc = Document()
    doc.add_heading("Promo Register Audit Brief", level=1)
    paragraph = (
        f"This audit checked {len(formatted)} promotional sales rows for register-price and promotional-window exceptions. "
        "A Price Error means the register price did not match the promotional price; a Window Error means the sale occurred outside the promotional window. "
        f"The data contained {totals['Price Errors']} Price Errors, {totals['Window Errors']} Window Errors, and {totals['Total Errors']} Total Errors overall. "
        f"The highest-priority SKUs by exception frequency include {sku_phrase}, which should be reviewed first with their affected stores. "
        "Implement automated register-price synchronization before each promotion launch and add daily exception monitoring for sales that post outside approved promotion dates."
    )
    doc.add_paragraph(paragraph)
    doc.save(BRIEF)
    print(f"Wrote Word brief: {BRIEF}")

    return totals


def validate_outputs():
    wb = load_workbook(AUDIT, data_only=False)
    expected_sheets = ["RawData", "Formatted Data", "Summary"]
    print(f"Validation sheet names: {wb.sheetnames}")
    if wb.sheetnames != expected_sheets:
        raise AssertionError(f"Sheet names mismatch: {wb.sheetnames!r}")

    ws_fmt = wb["Formatted Data"]
    fmt_headers = [cell.value for cell in ws_fmt[1]]
    print(f"Validation formatted headers ({len(fmt_headers)}): {fmt_headers}")
    if len(fmt_headers) != 12 or fmt_headers != FORMATTED_HEADERS:
        raise AssertionError("Formatted Data headers/column count mismatch")

    ws_sum = wb["Summary"]
    last_row = ws_sum.max_row
    summary_headers = [cell.value for cell in ws_sum[1]]
    if summary_headers != SUMMARY_HEADERS:
        raise AssertionError(f"Summary headers mismatch: {summary_headers!r}")
    grand_sku = ws_sum.cell(last_row, 1).value
    if grand_sku != "Grand Total":
        raise AssertionError(f"Summary last row SKU mismatch: {grand_sku!r}")
    price_total = ws_sum.cell(last_row, 3).value
    window_total = ws_sum.cell(last_row, 4).value
    total_errors = ws_sum.cell(last_row, 5).value
    print(f"Grand Total Price Errors: {price_total}")
    print(f"Grand Total Window Errors: {window_total}")
    print(f"Grand Total Total Errors: {total_errors}")

    if not os.path.exists(BRIEF):
        raise AssertionError(f"Brief missing: {BRIEF}")
    doc = Document(BRIEF)
    text = "\n".join(p.text for p in doc.paragraphs if p.text.strip())
    print("Brief text content:")
    print(text)


if __name__ == "__main__":
    build_outputs()
    validate_outputs()
